// Original displaywidth.Options.Rune on every legal Unicode scalar, two planes.
// stdout is raw width bytes only; stderr contains actual execution identities.
package main
import("bufio";"crypto/sha256";"encoding/hex";"encoding/json";"io";"os";"github.com/clipperhouse/displaywidth")
func main(){hash:=sha256.New();out:=bufio.NewWriter(io.MultiWriter(os.Stdout,hash));count:=0;for _,east:=range []bool{false,true}{opts:=displaywidth.Options{EastAsianWidth:east};for cp:=0;cp<=0x10ffff;cp++{if cp>=0xd800&&cp<=0xdfff{continue};if err:=out.WriteByte(byte(opts.Rune(rune(cp))));err!=nil{panic(err)};count++}};if err:=out.Flush();err!=nil{panic(err)};executable,err:=os.Executable();if err!=nil{panic(err)};binary,err:=os.ReadFile(executable);if err!=nil{panic(err)};identity:=sha256.Sum256(binary);if err:=json.NewEncoder(os.Stderr).Encode(map[string]any{"scope":"actual original displaywidth0.11 Options.Rune only; not twwidth ANSI/tab/env","planes":2,"plane_order":[]bool{false,true},"scalar_order":"ascending U0000..U10FFFF excluding D800..DFFF","actual_width_byte_count":count,"actual_raw_sha256":hex.EncodeToString(hash.Sum(nil)),"actual_binary_sha256":hex.EncodeToString(identity[:])});err!=nil{panic(err)}}
